// the solo: a random walk over the scale, chord tones on the beats (improvise)
const SOLO = improvise({
  start: 208, length: 94, rate: 2, seed: 68, swing: SW, lo: 10, hi: 29,
  phrase: 8, rest: 0.2, hold: 0.3, scale: () => SCALE, chord: x => (chordAt(x)?.[3] ?? [0]).map(n => mod(n, 12)),
}).map(([b, n, d]) => [b - 208, n, d])
const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[48,"A",0,1],[80,"A",0,1],[112,"A",0,1],[144,"A",0,1],[176,"REST",0,1],[208,"REST",0,1],[304,"A",2,1],[336,"A",2,1],[368,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[48,"REST",0,1],[176,"BRIDGE",0,1],[192,"BRIDGE",0,1],[208,"SOLO",0,1],[304,"REST",0,1],[368,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[48,"REST",0,1],[176,"REST",0,1],[208,"REST",0,1],[304,"HARMONY",0,1],[368,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- zunpet ------------------------------------------------------------------------------------
const track0 = {
  color: '#ffd166',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Zp = \\Rev\\,\\Dly\\Big[H_{2.8}\\big(1.0023g\\big) + 0.8\\,H_{3.4}\\big(0.9977g\\big)\\Big],\\quad H_b = 0.7y + 0.5\\BP_{450}y,\\ y = \\LP_{f_c}\\tfrac12\\big(\\saw g + \\saw 1.0023g\\big)e(t)","g = f\\cdot 2^{\\big(-0.4e^{-t/30\\text{мс}} + 0.28\\min(1,\\,(t - 0.18)^+/0.3)\\sin 2\\pi\\cdot 5.8T\\big)/12}\\ \\text{— подъезд снизу и позднее вибрато}"],
  audio({ bpm }) {
    const sec = 60 / bpm, a = horn({ bright: 2.8, seed: 61 }), b = horn({ bright: 3.4, seed: 67 }), echo = delay({ time: sec * 0.75, feedback: 0.24, wet: 0.17 }), verb = reverb({ room: 0.78, damp: 0.42, wet: 0.24 })
    let n = 0
    return x => {
      const m = leadAt(x), t = x * sec
      if (m) n = m.n
      const held = m ? m.τ * sec : 0, bend = m ? -0.4 * exp(-held / 0.03) + 0.28 * Math.min(1, Math.max(0, held - 0.18) / 0.3) * sin(TAU * 5.8 * t) : 0
      const f = hz(n + bend, C4), on = !!m && m.u < 0.94, vel = 0.8 + (0.15 * energy(x)) / 3
      const y = 0.5 * (a(f * 1.0023, on, vel) + 0.8 * b(f * 0.9977, on, vel))
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

// ---- piano -------------------------------------------------------------------------------------
const track1 = {
  color: '#ffffff',
  graph: x => { const m = lead2At(x); return m ? 1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = lead2At(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["P(f,t,v) = 0.35\\sum_{k=1}^{6}\\frac{v^{0.4+0.25k}}{k^{1.15}}\\big(0.7e^{-d_k t}+0.3e^{-0.12d_k t}\\big)\\big(\\sin 2\\pi f_k t+\\sin(2\\pi\\cdot1.0006 f_k t+k)\\big)","f_k = kf\\sqrt{1+0.0004k^2}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(pianoTone, { release: 0.4, life: 6 }), fire = trigger(), verb = reverb({ room: 0.86, damp: 0.35, wet: 0.35 })
    return x => {
      const m = lead2At(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.7 + 0.2 * hash(floor(4 * x), 3), m.d * sec + 0.4)
      const y = 0.297 * p()
      return verb(...pan(y, -0.3))
    }
  },
}

